namespace sv_7b9a09fd05b5497bbcb375574cb0c41d.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@* Reusable message input: textarea + send button *@

<div class="message-input">
    <textarea class="form-control" rows="2"
              placeholder="@Placeholder"
              @bind="text"
              @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary btn-sm mt-1" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonLabel
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string text = string.Empty;

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var msg = text.Trim();
        text = string.Empty;
        await OnSend.InvokeAsync(msg);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}

.message-input {
    padding: 12px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
}

.message-input textarea {
    resize: none;
    font-size: 0.9rem;
}

.message-input button {
    float: right;
}

@using sv_7b9a09fd05b5497bbcb375574cb0c41d.Services

<div class="message-item" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <strong class="message-author">@Message.Author</strong>
        <span class="message-time text-muted">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge badge rounded-pill bg-light text-dark"
                      @onclick="() => OnReact.InvokeAsync(reaction.Emoji)"
                      title="@string.Join(", ", reaction.Users)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ThreadReplyCount > 0)
    {
        <button class="btn btn-link btn-sm thread-link p-0" @onclick="() => OnOpenThread.InvokeAsync()">
            @ThreadReplyCount @(ThreadReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (showActions && ShowActions)
    {
        <div class="action-bar">
            <button class="btn btn-outline-secondary btn-sm" @onclick="() => OnOpenThread.InvokeAsync()" title="Reply in thread">
                💬 Reply
            </button>
            <div class="emoji-picker-wrapper">
                <button class="btn btn-outline-secondary btn-sm" @onclick="ToggleEmojiPicker" title="Add reaction">
                    😀
                </button>
                @if (showEmojiPicker)
                {
                    <div class="emoji-picker">
                        @foreach (var emoji in commonEmojis)
                        {
                            <span class="emoji-option" @onclick="() => SelectEmoji(emoji)">@emoji</span>
                        }
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ThreadReplyCount { get; set; }
    [Parameter] public bool ShowActions { get; set; } = true;
    [Parameter] public EventCallback OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }
}

.message-item {
    padding: 8px 16px;
    position: relative;
    border-radius: 4px;
    transition: background-color 0.15s;
}

.message-item:hover {
    background-color: #f8f9fa;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-size: 0.95rem;
}

.message-time {
    font-size: 0.75rem;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    white-space: pre-wrap;
    word-break: break-word;
}

.reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    cursor: pointer;
    font-size: 0.8rem;
    border: 1px solid #dee2e6;
    padding: 2px 8px;
}

.reaction-badge:hover {
    background-color: #e2e6ea !important;
}

.thread-link {
    font-size: 0.8rem;
    margin-top: 4px;
    text-decoration: none;
}

.action-bar {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 2px 4px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
    z-index: 10;
}

.action-bar .btn {
    font-size: 0.78rem;
    padding: 2px 6px;
}

.emoji-picker-wrapper {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 6px;
    padding: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 20;
    white-space: nowrap;
}

.emoji-option {
    cursor: pointer;
    font-size: 1.2rem;
    padding: 2px;
    border-radius: 4px;
    transition: background-color 0.15s;
}

.emoji-option:hover {
    background-color: #f0f0f0;
}

@using sv_7b9a09fd05b5497bbcb375574cb0c41d.Services

<div class="channel-list">
    <h6 class="channel-list-header px-3 py-2 mb-0">Channels</h6>
    <ul class="list-unstyled mb-0">
        @foreach (var channel in Channels)
        {
            <li class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
                @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
                <div class="channel-name">
                    <span class="channel-hash">#</span> @channel.Name
                    @if (channel.UnreadCount > 0)
                    {
                        <span class="badge bg-danger rounded-pill ms-auto">@channel.UnreadCount</span>
                    }
                </div>
                @if (!string.IsNullOrWhiteSpace(channel.Description))
                {
                    <div class="channel-desc text-muted">@Truncate(channel.Description, 40)</div>
                }
            </li>
        }
    </ul>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

.channel-list {
    height: 100%;
    overflow-y: auto;
    background: #2c2f33;
    color: #dcddde;
}

.channel-list-header {
    color: #fff;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: 0.5px;
    border-bottom: 1px solid #3a3d42;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 2px 8px;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #36393f;
}

.channel-item.active {
    background-color: #404449;
    color: #fff;
}

.channel-name {
    display: flex;
    align-items: center;
    font-weight: 500;
    font-size: 0.9rem;
}

.channel-hash {
    margin-right: 4px;
    opacity: 0.6;
}

.channel-desc {
    font-size: 0.72rem;
    margin-top: 1px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

@using sv_7b9a09fd05b5497bbcb375574cb0c41d.Services

<div class="message-area">
    @if (Channel is not null)
    {
        <div class="message-area-header">
            <h5 class="mb-0"><span class="text-muted">#</span> @Channel.Name</h5>
            <span class="text-muted small">@Channel.Description</span>
        </div>

        <div class="message-list" @onscroll="HandleScroll" @ref="messageListRef">
            @if (IsLoadingMore)
            {
                <div class="text-center py-2">
                    <span class="spinner-border spinner-border-sm text-muted"></span>
                </div>
            }

            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             ThreadReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="() => OnOpenThread.InvokeAsync(message.Id)"
                             OnReact="emoji => OnReact.InvokeAsync((message.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSend="OnSendMessage" />
    }
    else
    {
        <div class="d-flex align-items-center justify-content-center h-100 text-muted">
            Select a channel to start chatting
        </div>
    }
</div>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference messageListRef;

    private int GetReplyCount(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;

    private async Task HandleScroll()
    {
        // Scroll-to-top detection is handled via JS interop for precise scroll position,
        // but as a simplified approach we expose the callback for the parent to wire up.
        // The parent page triggers OnLoadMore when scroll reaches the top.
        await Task.CompletedTask;
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: #fff;
}

.message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

@using sv_7b9a09fd05b5497bbcb375574cb0c41d.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6 class="mb-0">Thread</h6>
        <button class="btn btn-sm btn-outline-secondary border-0" @onclick="OnClose" title="Close thread">✕</button>
    </div>

