+    private Channel? selectedChannel;
+    private int selectedChannelId;
+    private Message? threadRootMessage;
+
+    private bool isLoadingMore;
+    private bool hasMoreMessages = true;
+
+    private const int PageSize = 30;
+
+    private IJSObjectReference? jsModule;
+    private DotNetObjectReference<Chat>? dotNetRef;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+    }
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            dotNetRef = DotNetObjectReference.Create(this);
+            jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
+                "./_content/sv_7b9a09fd05b5497bbcb375574cb0c41d/Components/Pages/Chat.razor.js");
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        selectedChannelId = channelId;
+        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messages = [];
+        threadSummaries = [];
+        threadRootMessage = null;
+        threadReplies = [];
+        hasMoreMessages = true;
+
+        await LoadMessages();
+        await ChatService.MarkChannelReadAsync(channelId);
+
+        // Update unread count locally
+        var idx = channels.FindIndex(c => c.Id == channelId);
+        if (idx >= 0)
+        {
+            channels[idx] = channels[idx] with { UnreadCount = 0 };
+        }
+    }
+
+    private async Task LoadMessages()
+    {
+        var batch = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
+        if (batch.Count < PageSize)
+        {
+            hasMoreMessages = false;
+        }
+
+        // Prepend older messages
+        messages.InsertRange(0, batch);
+        BuildThreadSummaries();
+
+        // Set up scroll detection after messages load
+        await SetupScrollDetection();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || !hasMoreMessages) return;
+
+        isLoadingMore = true;
+        StateHasChanged();
+
+        await LoadMessages();
+
+        isLoadingMore = false;
+    }
+
+    [JSInvokable]
+    public async Task OnScrolledToTop()
+    {
+        await LoadMoreMessages();
+        StateHasChanged();
+    }
+
+    private async Task SetupScrollDetection()
+    {
+        if (jsModule is not null && dotNetRef is not null)
+        {
+            await jsModule.InvokeVoidAsync("observeScrollTop", ".message-list", dotNetRef);
+        }
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+    }
+
+    private void CloseThread()
+    {
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Optimistic update: add or increment reaction locally
+        var msg = messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (msg is not null)
+        {
+            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                if (!existing.Users.Contains("You"))
+                    existing.Users.Add("You");
+            }
+            else
+            {
+                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (selectedChannel is null) return;
+
+        var sent = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
+        messages.Add(sent);
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (selectedChannel is null || threadRootMessage is null) return;
+
+        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+
+        // Update thread summary count
+        var summary = threadSummaries.FirstOrDefault(t => t.RootMessageId == threadRootMessage.Id);
+        if (summary is not null)
+        {
+            var idx = threadSummaries.IndexOf(summary);
+            threadSummaries[idx] = summary with { ReplyCount = summary.ReplyCount + 1, LastReplyAt = DateTime.UtcNow };
+        }
+        else
+        {
+            threadSummaries.Add(new ThreadSummary(threadRootMessage.Id, 1, DateTime.UtcNow));
+        }
+    }
+
+    private void BuildThreadSummaries()
+    {
+        // Build summaries from messages that have replies pointing to them
+        var replyGroups = messages
+            .Where(m => m.ReplyToId.HasValue)
+            .GroupBy(m => m.ReplyToId!.Value)
+            .ToList();
+
+        foreach (var group in replyGroups)
+        {
+            if (!threadSummaries.Any(t => t.RootMessageId == group.Key))
+            {
+                threadSummaries.Add(new ThreadSummary(
+                    group.Key,
+                    group.Count(),
+                    group.Max(m => m.SentAt)));
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (jsModule is not null)
+        {
+            try { await jsModule.DisposeAsync(); } catch (JSDisconnectedException) { }
+        }
+        dotNetRef?.Dispose();
+    }
+}
+

